const store = require("../../src/database/store")

const COLLECTION_MAP = {
  course: "courses",
  blogPost: "blogPosts",
  ebook: "ebooks",
  lead: "leads",
  leadEbook: "leadEbooks",
  siteSettings: "siteSettings",
  user: "users"
}

function ensureCollection(name) {
  const currentStore = store.readStore()
  const collectionKey = COLLECTION_MAP[name] || `${name}s`

  if (collectionKey === "siteSettings") {
    if (currentStore.siteSettings === undefined) {
      currentStore.siteSettings = null
      store.writeStore(currentStore)
    }
    return collectionKey
  }

  if (!Array.isArray(currentStore[collectionKey])) {
    currentStore[collectionKey] = []
    store.writeStore(currentStore)
  }

  return collectionKey
}

function matchesWhere(record, where = {}) {
  return Object.entries(where).every(([key, value]) => record?.[key] === value)
}

function sortRecords(records, orderBy) {
  if (!orderBy || typeof orderBy !== "object") {
    return records
  }

  const [field, direction] = Object.entries(orderBy)[0] || []
  if (!field) {
    return records
  }

  return [...records].sort((left, right) => {
    const leftValue = left?.[field]
    const rightValue = right?.[field]

    if (leftValue === rightValue) {
      return 0
    }

    const factor = direction === "desc" ? -1 : 1
    return leftValue > rightValue ? factor : -factor
  })
}

function buildArrayDelegate(collectionName) {
  const collectionKey = ensureCollection(collectionName)

  return {
    async findMany(options = {}) {
      const currentStore = store.readStore()
      const records = Array.isArray(currentStore[collectionKey]) ? currentStore[collectionKey] : []
      const filtered = options.where ? records.filter((record) => matchesWhere(record, options.where)) : records
      return sortRecords(filtered, options.orderBy)
    },
    async findUnique(options = {}) {
      const records = await this.findMany(options)
      return records[0] || null
    },
    async findFirst(options = {}) {
      const records = await this.findMany(options)
      return records[0] || null
    },
    async create(options = {}) {
      const currentStore = store.readStore()
      const records = Array.isArray(currentStore[collectionKey]) ? currentStore[collectionKey] : []
      const nextId = records.length ? Math.max(...records.map((record) => Number(record.id) || 0)) + 1 : 1
      const now = new Date().toISOString()
      const data = { ...options.data }

      if (data.createdAt === undefined) {
        data.createdAt = now
      }
      if (data.updatedAt === undefined) {
        data.updatedAt = now
      }
      if (data.id === undefined) {
        data.id = nextId
      }

      records.push(data)
      currentStore[collectionKey] = records
      store.writeStore(currentStore)
      return data
    },
    async createMany(options = {}) {
      const dataList = Array.isArray(options.data) ? options.data : []
      const created = []

      for (const item of dataList) {
        created.push(await this.create({ data: item }))
      }

      return { count: created.length }
    },
    async update(options = {}) {
      const currentStore = store.readStore()
      const records = Array.isArray(currentStore[collectionKey]) ? currentStore[collectionKey] : []
      const index = records.findIndex((record) => matchesWhere(record, options.where || {}))

      if (index === -1) {
        throw new Error(`Record not found in ${collectionKey}`)
      }

      const updatedAt = new Date().toISOString()
      const updatedRecord = {
        ...records[index],
        ...options.data,
        updatedAt
      }

      records[index] = updatedRecord
      currentStore[collectionKey] = records
      store.writeStore(currentStore)
      return updatedRecord
    },
    async deleteMany(options = {}) {
      const currentStore = store.readStore()
      const records = Array.isArray(currentStore[collectionKey]) ? currentStore[collectionKey] : []
      const remaining = options.where ? records.filter((record) => !matchesWhere(record, options.where)) : []
      const deletedCount = records.length - remaining.length
      currentStore[collectionKey] = remaining
      store.writeStore(currentStore)
      return { count: deletedCount }
    }
  }
}

function buildObjectDelegate(collectionName) {
  const collectionKey = ensureCollection(collectionName)

  return {
    async findFirst() {
      const currentStore = store.readStore()
      return currentStore[collectionKey] || null
    },
    async create(options = {}) {
      const now = new Date().toISOString()
      const data = { ...options.data }
      if (data.createdAt === undefined) {
        data.createdAt = now
      }
      if (data.updatedAt === undefined) {
        data.updatedAt = now
      }
      const currentStore = store.readStore()
      currentStore[collectionKey] = data
      store.writeStore(currentStore)
      return data
    },
    async update(options = {}) {
      const currentStore = store.readStore()
      const current = currentStore[collectionKey] || {}
      const updated = { ...current, ...options.data, updatedAt: new Date().toISOString() }
      currentStore[collectionKey] = updated
      store.writeStore(currentStore)
      return updated
    }
  }
}

class PrismaClient {
  constructor() {
    return new Proxy(this, {
      get(_target, property) {
        if (property === "$disconnect") {
          return async () => {}
        }

        if (property === "$connect") {
          return async () => {}
        }

        if (property === "$transaction") {
          return async (operations) => Promise.all(operations)
        }

        if (typeof property === "string") {
          if (property === "siteSettings") {
            return buildObjectDelegate(property)
          }

          if (property in COLLECTION_MAP || /^(course|blogPost|ebook|lead|leadEbook|user)$/i.test(property)) {
            return buildArrayDelegate(property)
          }
        }

        return Reflect.get(_target, property)
      }
    })
  }
}

module.exports = {
  PrismaClient
}
